def check_equation(x, y, z):
    return x**3 + y**3 + z**3 - x**2 * y**2 * z**2 == 0

solutions = []
max_z = 15

for z in range(1, max_z + 1):
    for y in range(1, z + 1):
        for x in range(1, y + 1):
            if check_equation(x, y, z):
                solutions.append((x, y, z))

print("Found solutions:", solutions)

# Now I will write these solutions to notes.md
if solutions:
    notes_text = "Solutions found by brute force (z <= 15): " + str(solutions)
else:
    notes_text = "No solutions found by brute force (z <= 15)."

print("\nText to write to notes.md:", notes_text)

